#!/usr/bin/env bash
# Contract for tests/check_pr_commit_claims.sh: this gate is the only thing
# standing between a `git commit -C` carry-over and an upstream PR whose commit
# messages promise tests/ files the branch never carried, so its exit codes are
# pinned here.
#
# Every case is built in a throwaway repository from commit-tree and mktree
# objects, so the run depends on no ref, remote or worktree of the host checkout
# and leaves nothing behind to prune.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  commit-claims self-test (not inside a git checkout)\n'
    exit 125
}
gate=$root/tests/check_pr_commit_claims.sh
if [ ! -f "$gate" ]; then
    printf 'commit-claims self-test: gate missing at %s\n' "$gate" >&2
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp while native
# git.exe maps that name elsewhere, so a sandbox built there can be invisible
# to the shell that created it. Same reasoning as tests/check_pr_bodies_test.sh.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -u "${USERPROFILE:-}")
else
    tmpbase=${TMPDIR:-/tmp}
fi
tmp=$(mktemp -d "$tmpbase/pime-commit-claims-selftest.XXXXXX")
repo=$tmp/repo
trap 'rm -rf "$tmp"' EXIT

export GIT_AUTHOR_NAME=selftest GIT_AUTHOR_EMAIL=selftest@example.invalid
export GIT_COMMITTER_NAME=selftest GIT_COMMITTER_EMAIL=selftest@example.invalid

failures=0

# expect <want-code> <name> <branch-or-empty> [cwd]
expect() {
    local want=$1 name=$2 arg=$3 cwd=${4:-$repo} got
    if [ -n "$arg" ]; then
        ( cd "$cwd" && GITHUB_HEAD_REF= bash "$gate" "$arg" >"$tmp/out" 2>&1 )
    else
        ( cd "$cwd" && GITHUB_HEAD_REF= bash "$gate" >"$tmp/out" 2>&1 )
    fi
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s: want %s got %s\n' "$name" "$want" "$got"
        sed 's/^/      /' "$tmp/out"
        failures=$((failures + 1))
    else
        printf 'ok    %s\n' "$name"
    fi
}

git init -q "$repo" || { printf 'sandbox git init failed\n' >&2; exit 1; }

blob=$(printf 'value = 1\n' | git -C "$repo" hash-object -w --stdin)
testblob=$(printf 'def test_selftest():\n    pass\n' | git -C "$repo" hash-object -w --stdin)
git -C "$repo" remote add product https://github.com/EasyIME/PIME.git
# mktree builds one level, so a nested path needs its own subtree object.
base_tree=$(printf '100644 blob %s\tREADME.md\n' "$blob" | git -C "$repo" mktree)
python_sub=$(printf '100644 blob %s\ttool.py\n' "$blob" | git -C "$repo" mktree)
tests_sub=$(printf '100644 blob %s\ttest_selftest.py\n' "$testblob" | git -C "$repo" mktree)
product_tree=$(printf '100644 blob %s\tREADME.md\n040000 tree %s\tpython\n' \
    "$blob" "$python_sub" | git -C "$repo" mktree)
with_test_tree=$(printf '100644 blob %s\tREADME.md\n040000 tree %s\tpython\n040000 tree %s\ttests\n' \
    "$blob" "$python_sub" "$tests_sub" | git -C "$repo" mktree)

commit_of() { # <tree> <message> -> sha
    printf '%s\n' "$2" | git -C "$repo" commit-tree "$1" -p "$base"
}

base=$(printf 'initial\n' | git -C "$repo" commit-tree "$base_tree")
git -C "$repo" update-ref refs/remotes/product/master "$base"
git -C "$repo" update-ref refs/heads/master "$base"

# 1. Integration and local record branch names skip whatever they point at.
git -C "$repo" update-ref refs/heads/local/linux-master "$(commit_of "$product_tree" 'docs: harness note')"
expect 125 'integration branch name skips' local/linux-master

# 2. A product commit whose message names only its own change passes.
git -C "$repo" update-ref refs/heads/selftest/clean \
    "$(commit_of "$product_tree" 'fix(python): stop the tool dropping a value

Consult every return instead of the last one.

Architecture and design by someone. Implementation generated with AI
assistance from omp (model).')"
expect 0 'clean message passes' selftest/clean

# 2b. Prose about where a fix was tried, or about a reporter's test case, is not
#     a claim to have shipped one: the gate stays quiet on testing prose.
git -C "$repo" update-ref refs/heads/selftest/prose \
    "$(commit_of "$product_tree" 'fix(python): keep the delete loop running

Tested on Windows 11 x64 with the legacy console code page; the reported
test case no longer reproduces.')"
expect 0 'testing prose is not a harness claim' selftest/prose

# 3. The defect itself: a harness sentence copied by `git commit -C`, with no
#    tests/ path in the commit.
git -C "$repo" update-ref refs/heads/selftest/harness-claim \
    "$(commit_of "$product_tree" 'fix(python): let the editor finish deletes

Drop the debug prints and consult every return. The new test drives the
handler through the authenticated decorator.')"
expect 1 'message claiming a test the commit lacks fails' selftest/harness-claim

# 4. Same wording is honest once the commit really carries the test.
git -C "$repo" update-ref refs/heads/selftest/honest \
    "$(commit_of "$with_test_tree" 'fix(python): let the editor finish deletes

Drop the debug prints and consult every return. The new test drives the
handler through the authenticated decorator.')"
expect 0 'message claiming a test the commit carries passes' selftest/honest

# 5. A ref that is not a commit is not applicable, and neither is a detached
#    HEAD with no argument.
expect 125 'non-commit ref skips' "$blob"
git -C "$repo" update-ref HEAD "$(git -C "$repo" rev-parse refs/heads/selftest/clean)"
expect 125 'detached HEAD without argument skips' ''

# 6. Without an EasyIME/PIME remote there is no product base to judge against.
git -C "$repo" remote set-url product https://github.com/example/other.git
git -C "$repo" update-ref refs/remotes/product/master "$base"
expect 125 'no product remote skips' selftest/harness-claim

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
